import{_ as t,l as s,o as e,c as l,v as i,p as n,x as r,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"图同构直觉","description":"","frontmatter":{"title":"图同构直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/graph-isomorphism.md","filePath":"cs/graph-isomorphism.md","lastUpdated":1789023840000}'),m={name:"cs/graph-isomorphism.md"};function c(E,a,_,u,P,A){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="图同构直觉" tabindex="-1">图同构直觉 <a class="header-anchor" href="#图同构直觉" aria-label="Permalink to &quot;图同构直觉&quot;">​</a></h1><div class="epigraph"><p>是否存在保持边的双射，既未证明 NPC，也长期未进 P；实践靠不变量与个别化，理论侧有准多项式。</p><footer>—— 据 Read and Corneil, The Graph Isomorphism Disease, 1977；McKay, nauty；Babai, Graph Isomorphism in Quasipolynomial Time, 2016 整理</footer></div><p>上一课<a href="/cs/planar-algorithms">平面图算法</a>有线性平面性。图同构（GI）：是否 \\(G\\simeq H\\)。本课不重写平面嵌入。缺口是问题的<strong>复杂度地位</strong>与实用算法形状：度数序列、Weisfeiler–Leman 染色、个别化–加细，而不是再给一个 NPC 归约。本序列「连通、树与匹配」在此收束。下一单元最短路加速。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GI 在 NP：证书是双射。coNP 不明显（要证没有双射）。许多图类多项式：树、平面、有界度数（Luks）。一般图：Babai 2016 准多项式 \\(\\exp((\\log n)^{O(1)})\\)。实践：nauty 等用自同构群搜索 + 不变量剪枝，随机图上极快。</p><p>缺口是「不要当 NPC 教」，不是给出完整群论证明。</p><h3 id="同构不是哈密顿" tabindex="-1">同构不是哈密顿 <a class="header-anchor" href="#同构不是哈密顿" aria-label="Permalink to &quot;同构不是哈密顿&quot;">​</a></h3><p>哈密顿有简单的 NPC 归约；GI 没有已知的这类归约，也未被证明 P。不要把「看起来组合爆炸」写成 NPC。子图同构（含给定 \\(H\\)）是 NPC——那是另一问题。</p><p><span class="marginnote">Read–Corneil 1977 综述「疾病」。McKay 的 nauty 是标准工具。Babai 2016 准多项式（随后修订）。Weisfeiler–Leman 染色是高维不变量。后课 A* 换最短路启发式，不再问双射。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先比度数、连通支、谱等不变量。WL：按邻域色的多重集迭代加细，直到稳定；色相同未必同构（正则图）。个别化：固定某点打破对称，分支搜索。树同构：AHU 规范编码线性。</p>',11)),(e(),n(d,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%20%2F%20WL%22%5D%20--%3E%20EQ%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%EF%BC%9F%22%5D%0A%20%20EQ%20--%3E%20IND%5B%22%E4%B8%AA%E5%88%AB%E5%8C%96%E5%88%86%E6%94%AF%22%5D%0A%20%20EQ%20--%3E%20NO%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E5%88%99%E9%9D%9E%E5%90%8C%E6%9E%84%22%5D%0A%20%20IND%20--%3E%20AUT%5B%22%E8%87%AA%E5%90%8C%E6%9E%84%E6%90%9C%E7%B4%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>规范标记：给每个图一个串，相等当且仅当同构；实用算法常输出标记。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对称性（大自同构群）使分支爆炸，个别化针对轨道。平面图可用嵌入的组合映射。与着色：WL 是颜色细化，不是 \\(\\chi\\)。不要用指数枚举双射当主算法——\\(n!\\) 无剪枝。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Babai 全文，不写群的 Schreier–Sims。不把分子图同构当化学课。后课默认：GI 特殊；实用靠不变量+搜索；理论准多项式。下一课 A*：启发式最短路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GI 在 NP，未证 NPC，有准多项式。</li><li>子图同构才是 NPC；不要混。</li><li>实践：WL、个别化、nauty。</li><li>出处：Read and Corneil, 1977；Babai, 2016；McKay nauty。</li></ul>',7))])}const B=t(m,[["render",c]]);export{C as __pageData,B as default};
